cpp 实现步进电机的速度控制。通过计算循环时间间隔，累加需要发送的脉冲数，当累加值达到步进阈值时，根据方向执行步进操作并调整累加值，从而实现平滑的速度控制。 // loop 函数仅用于实现速度控制
void loop() {
  uint32_t currentLoopTime = micros();
  if (inMoving) {
    // 循环之间的间隔
    uint32_t dt = currentLoopTime - lastLoopTime;

    // 角度累加，以脉冲数为单位
    pulse2Send += speedPerPulse * dt;

    // 是否需要步进一格。
    if (abs(pulse2Send) >= 0.5) {
      step(pulse2Send > 0); // 根据方向，步进一格

      // 已完成步进，调整累加值
      if (pulse2Send > 0) {
        pulse2Send -= 1;
      } else {
        pulse2Send += 1;
      }
    }
  }

  lastLoopTime = currentLoopTime;
}

cpp 该代码基于 Arduino 平台，使用 `TimerOne` 库设置了一个周期为 1 秒（1,000,000 微秒）的定时器中断。在 `setup()` 函数中初始化内置 LED 引脚并启动定时器。每当定时器中断触发时，调用 `LED()` 函数，该函数通过静态变量 `light` 交替改变内置 LED（`LED_BUILTIN`）的高低电平状态，从而实现 LED 灯每秒闪烁一次（亮灭交替）的效果。 #include <TimerOne.h>

void setup() {
  //初始化LED端口
  pinMode(LED_BUILTIN, OUTPUT);

  // 每 1 s 触发一次时间中断
  Timer1.initialize(long(1 * 1E6));

  // 设置中断响应函数
  Timer1.attachInterrupt(LED);

  // 启动时间中断
  Timer1.start();
}

void LED() {
  static bool light = true;

  digitalWrite(LED_BUILTIN, light);
  light = !light;
}
